      },
      tags: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const mockDispatchClient = {
      createDispatch: vi.fn().mockRejectedValue(new Error("Dispatch failed")),
    };

    vi.mocked(AgentDispatchClient).mockImplementation(() => mockDispatchClient as any);

    await expect(callOpportunityImmediately(opportunityId)).rejects.toThrow("Dispatch failed");
  });

  it("should handle errors in room creation gracefully", async () => {
    const opportunityId = "opp-error-room";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-8",
      candidate: {
        id: "candidate-8",
