        channel: "phone",
        triggeredAt: new Date(),
        cancelledAt: null,
        scheduledAt: new Date("2024-01-01"),
      },
      {
        id: "item-2",
        opportunityId,
        channel: "email",
        triggeredAt: new Date(),
        cancelledAt: null,
        scheduledAt: new Date("2024-01-02"),
      },
      {
        id: "item-3",
        opportunityId,
        channel: "phone",
        triggeredAt: null,
        cancelledAt: null, // Not processed yet
        scheduledAt: new Date("2024-01-03"),
      },
    ] as OpportunitySequenceItem[]);

    const result = await checkAndHandleSequenceCompletion({
      opportunityId,
      lastProcessedItemId,
    });

    // Should not end because not all items are processed
    expect(result).toBe(false);
    expect(db.opportunity.update).not.toHaveBeenCalled();
  });

  it("should return false when opportunity not found in database", async () => {
    const opportunityId = "opp-11";
    const lastProcessedItemId = "item-1";

    vi.mocked(db.opportunitySequenceItem.findMany).mockResolvedValue([
      {
        id: "item-1",
        opportunityId,
        channel: "email",
        triggeredAt: new Date(),
