});

describe("callOpportunityImmediately", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    // Mock environment variables
    vi.stubEnv("LIVEKIT_URL_INBOUND", "ws://livekit-inbound.example.com");
    vi.stubEnv("LIVEKIT_API_KEY_INBOUND", "inbound-api-key");
    vi.stubEnv("LIVEKIT_API_SECRET_INBOUND", "inbound-api-secret");
    vi.stubEnv("LIVEKIT_URL", "ws://livekit.example.com");
    vi.stubEnv("LIVEKIT_API_KEY", "api-key");
    vi.stubEnv("LIVEKIT_API_SECRET", "api-secret");
  });

  afterEach(() => {
    vi.clearAllMocks();
    vi.unstubAllEnvs();
  });

  it("should dispatch agent for v3 schema version", async () => {
    const opportunityId = "opp-v3-1";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-1",
      candidate: {
        id: "candidate-1",
        firstName: "John",
        lastName: "Doe",
        email: "john@example.com",
        phoneNumber: "+15555551234",
        engagements: [],
      },
      job: {
        id: "job-1",
        status: "published",
        resumeCallsEnabled: true,
        schemaVersion: "v3",
      },
      tags: [],
      engagements: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const mockDispatchClient = {
      createDispatch: vi.fn().mockResolvedValue({
        id: "dispatch-v3-123",
        room: `opportunity-${opportunityId}`,
        agentName: "routing_agent",
      }),
    };

    vi.mocked(AgentDispatchClient).mockImplementation(() => mockDispatchClient as any);

    const result = await callOpportunityImmediately(opportunityId);

    expect(result.called).toBe(true);
    expect(result.roomName).toBe(`opportunity-${opportunityId}`);

    // Verify agent dispatch was called with correct parameters
    expect(mockDispatchClient.createDispatch).toHaveBeenCalledWith(
      `opportunity-${opportunityId}`,
      "routing_agent",
      {
        metadata: JSON.stringify({
          opportunity_id: opportunityId,
          kind: "outbound",
        }),
      }
    );

    // Verify correct LiveKit credentials were used for v3
    expect(AgentDispatchClient).toHaveBeenCalledWith(
      "ws://livekit-inbound.example.com",
      "inbound-api-key",
      "inbound-api-secret"
    );

    // Verify RoomServiceClient was NOT called for v3
    expect(RoomServiceClient).not.toHaveBeenCalled();
  });

  it("should create room directly for v2/legacy schema version", async () => {
    const opportunityId = "opp-v2-1";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-2",
      candidate: {
        id: "candidate-2",
        firstName: "Jane",
        lastName: "Smith",
        email: "jane@example.com",
        phoneNumber: "+15555552345",
        engagements: [],
      },
      job: {
        id: "job-2",
        status: "published",
        resumeCallsEnabled: true,
        schemaVersion: "v2", // v2 schema
      },
      tags: [],
      engagements: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const mockRoomService = {
      createRoom: vi.fn().mockResolvedValue({
        name: `opportunity-${opportunityId}`,
        sid: "room-sid-123",
      }),
    };

    vi.mocked(RoomServiceClient).mockImplementation(() => mockRoomService as any);

    const result = await callOpportunityImmediately(opportunityId);

    expect(result.called).toBe(true);
    expect(result.roomName).toBe(`opportunity-${opportunityId}`);

    // Verify room was created with correct parameters
    expect(mockRoomService.createRoom).toHaveBeenCalledWith({
      name: `opportunity-${opportunityId}`,
      emptyTimeout: 60 * 60,
    });

    // Verify correct LiveKit credentials were used for v2
    expect(RoomServiceClient).toHaveBeenCalledWith(
      "ws://livekit.example.com",
      "api-key",
      "api-secret"
    );

    // Verify AgentDispatchClient was NOT called for v2
    expect(AgentDispatchClient).not.toHaveBeenCalled();
  });

  it("should handle opportunities without schema version (legacy)", async () => {
    const opportunityId = "opp-legacy-1";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-3",
      candidate: {
        id: "candidate-3",
        firstName: "Bob",
        lastName: "Johnson",
        email: "bob@example.com",
        phoneNumber: "+15555553456",
        engagements: [],
      },
      job: {
        id: "job-3",
        status: "published",
        resumeCallsEnabled: true,
        schemaVersion: null, // No schema version (legacy)
      },
      tags: [],
      engagements: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const mockRoomService = {
      createRoom: vi.fn().mockResolvedValue({
        name: `opportunity-${opportunityId}`,
        sid: "room-sid-456",
      }),
    };

    vi.mocked(RoomServiceClient).mockImplementation(() => mockRoomService as any);

    const result = await callOpportunityImmediately(opportunityId);

    expect(result.called).toBe(true);
    expect(result.roomName).toBe(`opportunity-${opportunityId}`);

    // Verify room was created (legacy behavior)
    expect(mockRoomService.createRoom).toHaveBeenCalled();
    expect(AgentDispatchClient).not.toHaveBeenCalled();
  });

  it("should return called:false when opportunity not found", async () => {
    const opportunityId = "non-existent";

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(null);

    const result = await callOpportunityImmediately(opportunityId);

    expect(result.called).toBe(false);
    expect(result.roomName).toBeUndefined();
    expect(RoomServiceClient).not.toHaveBeenCalled();
    expect(AgentDispatchClient).not.toHaveBeenCalled();
  });

  it("should return called:false when candidate phone number is missing", async () => {
    const opportunityId = "opp-no-phone";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-4",
      candidate: {
        id: "candidate-4",
        firstName: "Alice",
        lastName: "Wonder",
        email: "alice@example.com",
        phoneNumber: null, // No phone number
        engagements: [],
      },
      job: {
        id: "job-4",
        status: "published",
        resumeCallsEnabled: true,
        schemaVersion: "v3",
      },
      tags: [],
      engagements: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const result = await callOpportunityImmediately(opportunityId);

    expect(result.called).toBe(false);
    expect(result.roomName).toBeUndefined();
    expect(RoomServiceClient).not.toHaveBeenCalled();
    expect(AgentDispatchClient).not.toHaveBeenCalled();
  });

  it("should return called:false when job status is not published", async () => {
    const opportunityId = "opp-draft-job";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-5",
      candidate: {
        id: "candidate-5",
        firstName: "Charlie",
        lastName: "Brown",
        email: "charlie@example.com",
        phoneNumber: "+15555554567",
        engagements: [],
      },
      job: {
        id: "job-5",
        status: "draft", // Not published
        resumeCallsEnabled: true,
        schemaVersion: "v3",
      },
      tags: [],
      engagements: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const result = await callOpportunityImmediately(opportunityId);

    expect(result.called).toBe(false);
    expect(result.roomName).toBeUndefined();
    expect(RoomServiceClient).not.toHaveBeenCalled();
    expect(AgentDispatchClient).not.toHaveBeenCalled();
  });

  it("should return called:false when resume calls are disabled", async () => {
    const opportunityId = "opp-no-resume";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-6",
      candidate: {
        id: "candidate-6",
        firstName: "David",
        lastName: "Miller",
        email: "david@example.com",
        phoneNumber: "+15555555678",
        engagements: [],
      },
      job: {
        id: "job-6",
        status: "published",
        resumeCallsEnabled: false, // Resume calls disabled
        schemaVersion: "v3",
      },
      tags: [],
      engagements: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const result = await callOpportunityImmediately(opportunityId);

    expect(result.called).toBe(false);
    expect(result.roomName).toBeUndefined();
    expect(RoomServiceClient).not.toHaveBeenCalled();
    expect(AgentDispatchClient).not.toHaveBeenCalled();
  });

  it("should handle errors in agent dispatch gracefully", async () => {
    const opportunityId = "opp-error-dispatch";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-7",
      candidate: {
        id: "candidate-7",
        firstName: "Eve",
        lastName: "Taylor",
        email: "eve@example.com",
        phoneNumber: "+15555556789",
        engagements: [],
      },
      job: {
        id: "job-7",
        status: "published",
        resumeCallsEnabled: true,
        schemaVersion: "v3",
      },
      tags: [],
      engagements: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const mockDispatchClient = {
      createDispatch: vi.fn().mockRejectedValue(new Error("Dispatch failed")),
    };

    vi.mocked(AgentDispatchClient).mockImplementation(() => mockDispatchClient as any);

    await expect(callOpportunityImmediately(opportunityId)).rejects.toThrow("Dispatch failed");
  });

  it("should handle errors in room creation gracefully", async () => {
    const opportunityId = "opp-error-room";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-8",
      candidate: {
        id: "candidate-8",
        firstName: "Frank",
        lastName: "Wilson",
        email: "frank@example.com",
        phoneNumber: "+15555557890",
      },
      job: {
        id: "job-8",
        status: "published",
        resumeCallsEnabled: true,
        schemaVersion: "v2",
      },
      tags: [],
      engagements: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const mockRoomService = {
      createRoom: vi.fn().mockRejectedValue(new Error("Room creation failed")),
    };

    vi.mocked(RoomServiceClient).mockImplementation(() => mockRoomService as any);

    await expect(callOpportunityImmediately(opportunityId)).rejects.toThrow("Room creation failed");
  });
});

