export enum JobStatus {
  ACTIVE = "active",
  PAUSED = "paused",
  CLOSED = "closed",
}

export enum JobSource {
  MANUAL = "manual",
  ATS_CEIPAL = "ceipal",
  ATS_KLEOS = "kleos",
  ATS_GREENHOUSE = "greenhouse",
  ATS_ASHBY = "ashby",
  ATS_TEMPWORKS = "tempworks",
  ATS_BULLHORN = "bullhorn",
  ATS_SMART_RECRUITERS = "smart_recruiters",
  ATS_SALESFORCE = "salesforce",
  ATS_HUBSPOT = "hubspot",
  // Kombo-based integrations
  ATS_KOMBO_SMART_RECRUITERS = "kombo_smart_recruiters",
  ATS_KOMBO_GREENHOUSE = "kombo_greenhouse",
  ATS_KOMBO_LEVER = "kombo_lever",
  ATS_KOMBO_WORKDAY = "kombo_workday",
  ATS_KOMBO_ASHBY = "kombo_ashby",
  ATS_KOMBO_WORKABLE = "kombo_workable",
}

export enum JobQualificationType {
  MANDATORY = "mandatory",
  PREFERRED = "preferred",
}

export const jobCreationSteps = {
  setup: {
    index: 0,
    label: "Setup",
    path: "setup",
  },
  qualifications: {
    index: 1,
    label: "Qualifications",
    path: "qualifications",
  },
  flow: {
    index: 2,
    label: "Flow",
    path: "flow",
  },
