        channel: "email",
        triggeredAt: new Date(),
        cancelledAt: null,
        scheduledAt: new Date("2024-01-01"),
      },
      {
        id: "item-2",
        opportunityId,
        channel: "phone",
        triggeredAt: null,
        cancelledAt: null, // Not processed yet
        scheduledAt: new Date("2024-01-02"),
      },
