    const result = await checkAndHandleSequenceCompletion({
      opportunityId,
      lastProcessedItemId,
    });

    expect(result).toBe(false);
    expect(db.opportunity.update).not.toHaveBeenCalled();
  });

  it("should NOT update if opportunity is already in terminal state", async () => {
    const opportunityId = "opp-7";
    const lastProcessedItemId = "item-1";

    vi.mocked(db.opportunitySequenceItem.findMany).mockResolvedValue([
      {
        id: "item-1",
        opportunityId,
        channel: "email",
        triggeredAt: new Date(),
        cancelledAt: null,
        scheduledAt: new Date("2024-01-01"),
      },
    ] as OpportunitySequenceItem[]);

    vi.mocked(db.opportunity.findUnique).mockResolvedValue({
      status: OpportunityStatus.completed, // Already in terminal state
