        phoneNumber: "+15555555678",
        engagements: [],
      },
      job: {
        id: "job-6",
        status: "active",
        resumeCallsEnabled: false, // Resume calls disabled
        schemaVersion: "v3",
      },
      tags: [],
      engagements: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const result = await callOpportunityImmediately(opportunityId);

    expect(result.called).toBe(false);
    expect(result.roomName).toBeUndefined();
    expect(RoomServiceClient).not.toHaveBeenCalled();
    expect(AgentDispatchClient).not.toHaveBeenCalled();
  });

  it("should handle errors in agent dispatch gracefully", async () => {
    const opportunityId = "opp-error-dispatch";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-7",
      candidate: {
        id: "candidate-7",
        firstName: "Eve",
        lastName: "Taylor",
        email: "eve@example.com",
        phoneNumber: "+15555556789",
        engagements: [],
      },
      job: {
        id: "job-7",
