import { nanoid } from "nanoid";

// TODO update this to use opportunityId
export function generateRoomName(opportunityId: string): string {
  return `profileId:${opportunityId}_${nanoid(12)}`;
}

// TODO this will be changed to opportunityId
export function parseOpportunityIdRoomName(roomName: string): string | null {
  if (!roomName.startsWith("profileId:")) {
    return null;
  }

  const parts = roomName.split(":");
  if (parts.length !== 2) {
    return null;
  }

  const [prefix, rest] = parts;
  if (prefix !== "profileId" || !rest) {
    return null;
  }

  const opportunityId = rest.split("_")[0];
  return opportunityId || null;
}

export function parseJobIdFromDemoRoomName(roomName: string): {
  jobId: string;
  opportunityId: string | null;
} | null {
  if (!roomName.startsWith("demo:")) {
    return null;
  }

  const parts = roomName.split(":");
  if (parts.length !== 2) {
    return null;
  }

  const [prefix, rest] = parts;
  if (prefix !== "demo" || !rest) {
    return null;
  }

  // The room name is of the form demo:jobId_profileId_uniqueId or demo:jobId_uniqueId
  const infoParts = rest.split("_");

  const jobId = infoParts[0] ?? "";
  let opportunityId: string | null = null;

