import {
  type Job,
  type Opportunity,
  type OpportunitySequenceItem,
  OpportunityStatus,
} from "@purplefish-ai/db";
import { db } from "@purplefish-ai/db/server";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { AgentDispatchClient, RoomServiceClient } from "livekit-server-sdk";

import {
  callOpportunityImmediately,
  checkAndHandleSequenceCompletion,
  getRemainingSequenceItems,
} from "./opportunities";
import { moveOpportunityToNextStage } from "./stages";

// Mock the database
vi.mock("@purplefish-ai/db/server", () => ({
  db: {
    opportunitySequenceItem: {
      count: vi.fn(),
      findMany: vi.fn(),
    },
    opportunity: {
      findUnique: vi.fn(),
      update: vi.fn(),
    },
    engagement: {
      findFirst: vi.fn(),
      create: vi.fn(),
    },
    auditLog: {
      create: vi.fn(),
    },
  },
}));

// Mock the stages module
vi.mock("./stages", () => ({
  moveOpportunityToNextStage: vi.fn(),
}));

// Mock the inngest client
vi.mock("../inngest/client", () => ({
  inngest: {
    send: vi.fn(),
  },
}));

// Mock LiveKit SDK
vi.mock("livekit-server-sdk", () => ({
  RoomServiceClient: vi.fn().mockImplementation(() => ({
    createRoom: vi.fn().mockResolvedValue({ name: "test-room" }),
  })),
  AgentDispatchClient: vi.fn().mockImplementation(() => ({
    createDispatch: vi.fn().mockResolvedValue({ 
      id: "dispatch-123",
      room: "test-room",
      agentName: "routing_agent" 
    }),
  })),
}));

describe("getRemainingSequenceItems", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    // Mock Date.now() to ensure consistent test behavior
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2024-01-15T12:00:00Z"));
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it("should count remaining sequence items scheduled in the future", async () => {
    const opportunityId = "test-opportunity-id";
    const expectedCount = 3;

    vi.mocked(db.opportunitySequenceItem.count).mockResolvedValue(
      expectedCount,
    );

    const result = await getRemainingSequenceItems(opportunityId);

    expect(result).toBe(expectedCount);
    expect(db.opportunitySequenceItem.count).toHaveBeenCalledWith({
      where: {
        opportunityId,
        scheduledAt: {
          gt: new Date("2024-01-15T12:00:00Z"),
        },
        triggeredAt: null,
        cancelledAt: null,
      },
    });
  });

  it("should return 0 when no future sequence items exist", async () => {
    const opportunityId = "test-opportunity-id-2";

    vi.mocked(db.opportunitySequenceItem.count).mockResolvedValue(0);

    const result = await getRemainingSequenceItems(opportunityId);

    expect(result).toBe(0);
    expect(db.opportunitySequenceItem.count).toHaveBeenCalledOnce();
  });

  it("should exclude triggered sequence items", async () => {
    const opportunityId = "test-opportunity-id-3";

    vi.mocked(db.opportunitySequenceItem.count).mockResolvedValue(2);

    await getRemainingSequenceItems(opportunityId);

    const mockCalls = vi.mocked(db.opportunitySequenceItem.count).mock.calls;
    expect(mockCalls).toHaveLength(1);
    const callArgs = mockCalls[0]![0];
    expect(callArgs?.where?.triggeredAt).toBeNull();
  });

  it("should exclude cancelled sequence items", async () => {
    const opportunityId = "test-opportunity-id-4";

    vi.mocked(db.opportunitySequenceItem.count).mockResolvedValue(1);

    await getRemainingSequenceItems(opportunityId);

    const mockCalls = vi.mocked(db.opportunitySequenceItem.count).mock.calls;
    expect(mockCalls).toHaveLength(1);
    const callArgs = mockCalls[0]![0];
    expect(callArgs?.where?.cancelledAt).toBeNull();
  });

  it("should handle database errors gracefully", async () => {
    const opportunityId = "test-opportunity-id-5";
    const dbError = new Error("Database connection failed");

    vi.mocked(db.opportunitySequenceItem.count).mockRejectedValue(dbError);

    await expect(getRemainingSequenceItems(opportunityId)).rejects.toThrow(
      "Database connection failed",
    );
  });

  it("should work with different timezone contexts", async () => {
    const opportunityId = "test-opportunity-id-6";

    // Change system time to a different timezone
    vi.setSystemTime(new Date("2024-01-15T00:00:00-08:00")); // PST

    vi.mocked(db.opportunitySequenceItem.count).mockResolvedValue(5);

    await getRemainingSequenceItems(opportunityId);

    const mockCalls = vi.mocked(db.opportunitySequenceItem.count).mock.calls;
    expect(mockCalls).toHaveLength(1);
    const callArgs = mockCalls[0]![0];
    // Should use the Date object which handles timezone conversion internally
    expect(callArgs?.where?.scheduledAt).toMatchObject({
      gt: expect.any(Date),
    });
  });

  it("should handle large result counts", async () => {
    const opportunityId = "test-opportunity-id-7";
    const largeCount = 1000000;

    vi.mocked(db.opportunitySequenceItem.count).mockResolvedValue(largeCount);

    const result = await getRemainingSequenceItems(opportunityId);

    expect(result).toBe(largeCount);
  });

  it("should be called with exact parameters", async () => {
    const opportunityId = "specific-opportunity-123";

    vi.mocked(db.opportunitySequenceItem.count).mockResolvedValue(7);

    await getRemainingSequenceItems(opportunityId);

    expect(db.opportunitySequenceItem.count).toHaveBeenCalledTimes(1);
    expect(db.opportunitySequenceItem.count).toHaveBeenCalledWith({
      where: {
        opportunityId: "specific-opportunity-123",
        scheduledAt: {
          gt: expect.any(Date),
        },
        triggeredAt: null,
        cancelledAt: null,
      },
    });
  });
});

describe("checkAndHandleSequenceCompletion", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.clearAllMocks();
  });

  it("should end sequence when last item is email and it was sent", async () => {
    const opportunityId = "opp-1";
