describe("callOpportunityImmediately", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    // Mock environment variables
    vi.stubEnv("LIVEKIT_URL_INBOUND", "ws://livekit-inbound.example.com");
    vi.stubEnv("LIVEKIT_API_KEY_INBOUND", "inbound-api-key");
    vi.stubEnv("LIVEKIT_API_SECRET_INBOUND", "inbound-api-secret");
    vi.stubEnv("LIVEKIT_URL", "ws://livekit.example.com");
    vi.stubEnv("LIVEKIT_API_KEY", "api-key");
    vi.stubEnv("LIVEKIT_API_SECRET", "api-secret");

    // Mock engagement lookup to return null (no existing engagement)
    vi.mocked(db.engagement.findFirst).mockResolvedValue(null);

    // Mock engagement creation
    vi.mocked(db.engagement.create).mockResolvedValue({
      id: "engagement-123",
      roomName: "opportunity-test",
    } as any);
  });

  afterEach(() => {
    vi.clearAllMocks();
    vi.unstubAllEnvs();
  });

  it("should dispatch agent for v3 schema version", async () => {
    const opportunityId = "opp-v3-1";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-1",
      candidate: {
        id: "candidate-1",
        firstName: "John",
        lastName: "Doe",
        email: "john@example.com",
        phoneNumber: "+15555551234",
        engagements: [],
        isBot: false,
      },
      job: {
        id: "job-1",
        status: "active",
        resumeCallsEnabled: true,
        schemaVersion: "v3",
      },
      tags: [],
      engagements: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const mockDispatchClient = {
      createDispatch: vi.fn().mockResolvedValue({
        id: "dispatch-v3-123",
        room: `opportunity-${opportunityId}`,
        agentName: "routing_agent",
      }),
    };

    vi.mocked(AgentDispatchClient).mockImplementation(() => mockDispatchClient as any);

    const result = await callOpportunityImmediately(opportunityId);

    expect(result.called).toBe(true);
    expect(result.roomName).toBe(`opportunity-${opportunityId}`);

    // Verify agent dispatch was called with correct parameters
    expect(mockDispatchClient.createDispatch).toHaveBeenCalledWith(
      `opportunity-${opportunityId}`,
      "routing_agent",
      {
        metadata: JSON.stringify({
          opportunity_id: opportunityId,
          kind: "outbound",
        }),
      }
    );

    // Verify correct LiveKit credentials were used for v3
    expect(AgentDispatchClient).toHaveBeenCalledWith(
      "ws://livekit-inbound.example.com",
      "inbound-api-key",
      "inbound-api-secret"
    );

    // Verify RoomServiceClient was NOT called for v3
    expect(RoomServiceClient).not.toHaveBeenCalled();
  });

  it("should create room directly for v2/legacy schema version", async () => {
    const opportunityId = "opp-v2-1";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-2",
      candidate: {
        id: "candidate-2",
        firstName: "Jane",
        lastName: "Smith",
        email: "jane@example.com",
        phoneNumber: "+15555552345",
        engagements: [],
        isBot: false,
      },
      job: {
        id: "job-2",
        status: "active",
        resumeCallsEnabled: true,
        schemaVersion: "v2", // v2 schema
      },
      tags: [],
      engagements: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const mockRoomService = {
      createRoom: vi.fn().mockResolvedValue({
        name: `opportunity-${opportunityId}`,
        sid: "room-sid-123",
      }),
    };

    vi.mocked(RoomServiceClient).mockImplementation(() => mockRoomService as any);

    const result = await callOpportunityImmediately(opportunityId);

    expect(result.called).toBe(true);
    expect(result.roomName).toBe(`opportunity-${opportunityId}`);

    // Verify room was created with correct parameters
    expect(mockRoomService.createRoom).toHaveBeenCalledWith({
      name: `opportunity-${opportunityId}`,
      emptyTimeout: 60 * 60,
    });

    // Verify correct LiveKit credentials were used for v2
    expect(RoomServiceClient).toHaveBeenCalledWith(
      "ws://livekit.example.com",
      "api-key",
      "api-secret"
    );

    // Verify AgentDispatchClient was NOT called for v2
    expect(AgentDispatchClient).not.toHaveBeenCalled();
  });

  it("should handle opportunities without schema version (legacy)", async () => {
    const opportunityId = "opp-legacy-1";
    const mockOpportunity = {
      id: opportunityId,
      candidateId: "candidate-3",
      candidate: {
        id: "candidate-3",
        firstName: "Bob",
        lastName: "Johnson",
        email: "bob@example.com",
        phoneNumber: "+15555553456",
        engagements: [],
        isBot: false,
      },
      job: {
        id: "job-3",
        status: "active",
        resumeCallsEnabled: true,
        schemaVersion: null, // No schema version (legacy)
      },
      tags: [],
      engagements: [],
    };

    vi.mocked(db.opportunity.findUnique).mockResolvedValue(mockOpportunity as any);

    const mockRoomService = {
      createRoom: vi.fn().mockResolvedValue({
        name: `opportunity-${opportunityId}`,
        sid: "room-sid-456",
      }),
    };

    vi.mocked(RoomServiceClient).mockImplementation(() => mockRoomService as any);

    const result = await callOpportunityImmediately(opportunityId);

    expect(result.called).toBe(true);
    expect(result.roomName).toBe(`opportunity-${opportunityId}`);

    // Verify room was created (legacy behavior)
    expect(mockRoomService.createRoom).toHaveBeenCalled();
    expect(AgentDispatchClient).not.toHaveBeenCalled();
  });

  it("should throw error when opportunity not found", async () => {
    const opportunityId = "non-existent";

